using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class F1DetailFinish {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_RoofLiftWilderness/");
 static void Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");}
 public static object Headroom(){Check();File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_20261113/candidate/FW_LiftShaft.fbx"),E+"FW_LiftShaft.fbx",true);AssetDatabase.ImportAsset(E+"FW_LiftShaft.fbx",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var root=GameObject.Find("F1_VL_LiftAssembly").transform;root.Find("Sheave").localPosition=new Vector3(-1.2f,5.55f,-.6f);var hoist=root.Find("FixedShaft/MachineBedMotorBrake");hoist.localPosition=new Vector3(0,.75f,0);PrefabUtility.RecordPrefabInstancePropertyModifications(hoist);var wrap=root.Find("Ropes/FixedWrap");wrap.localPosition=new Vector3(-1.2f,5.55f,-.6f);PrefabUtility.RecordPrefabInstancePropertyModifications(wrap);foreach(string name in new[]{"ToCar","ToCounterweight"}){var t=root.Find("Ropes/"+name);t.localPosition=new Vector3(name=="ToCar"?0:-2.4f,5.55f,-.6f);t.localScale=new Vector3(1,name=="ToCar"?1.76f:19.79f,1);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}var s=SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);return new{sheaveY=5.55f,ceilingUnderside=6.9f,carSlingTop=3.79f,wheelBottom=4.315f,headClearance=.525f};}
 public static object LowerLanding(){Check();File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_20261113/candidate/FW_LiftShaft.fbx"),E+"FW_LiftShaft.fbx",true);AssetDatabase.ImportAsset(E+"FW_LiftShaft.fbx",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var shaft=GameObject.Find("F1_VL_LiftAssembly").transform.Find("FixedShaft");if(!shaft.Find("Landing_B1")){var g=new GameObject("Landing_B1");g.transform.SetParent(shaft,false);g.transform.localPosition=new Vector3(0,-18,0);foreach(string name in new[]{"LandingFrameAndSill","LandingDoorLeft","LandingDoorRight"}){var source=shaft.Find(name);var copy=UnityEngine.Object.Instantiate(source.gameObject,g.transform);copy.name=name;copy.transform.localPosition=source.localPosition;if(name=="LandingDoorLeft")copy.transform.localPosition=new Vector3(-.655f,0,-2.86f);if(name=="LandingDoorRight")copy.transform.localPosition=new Vector3(.655f,0,-2.86f);}}
 var s=SceneManager.GetActiveScene();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);return new{lowerLanding=true};}
 public static object Reflections(){Check();var s=SceneManager.GetActiveScene();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf,async=ShaderUtil.allowAsyncCompilation;var results=new List<object>();try{player.SetActive(false);ShaderUtil.allowAsyncCompilation=false;foreach(var probe in GameObject.Find("1F_AbandonedFactory").GetComponentsInChildren<ReflectionProbe>()){string path=AssetDatabase.GetAssetPath(probe.customBakedTexture);if(!path.StartsWith(E+"Textures/AE_Reflection_"))continue;var mode=probe.mode;probe.mode=ReflectionProbeMode.Baked;try{if(!Lightmapping.BakeReflectionProbe(probe,path))throw new Exception("Reflection "+probe.name);}finally{probe.mode=mode;}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);results.Add(new{probe.name,path});}}finally{player.SetActive(active);ShaderUtil.allowAsyncCompilation=async;EditorSceneManager.OpenScene(s.path);}File.WriteAllText(Out+"reflections.json",JsonConvert.SerializeObject(results,Formatting.Indented));return new{probes=results.Count};}
 public static object Occlusion(){Check();StaticOcclusionCulling.Clear();StaticOcclusionCulling.smallestOccluder=3;StaticOcclusionCulling.smallestHole=.7f;StaticOcclusionCulling.backfaceThreshold=100;bool started=StaticOcclusionCulling.GenerateInBackground();return new{started};}
 public static object BakeFactory(){if(Application.isPlaying||StaticOcclusionCulling.isRunning)throw new Exception("Idle edit required");var s=SceneManager.GetActiveScene();string path="Assets/Afrer_Seconds/01.Scenes/Stage/Level_1F_Factory/OcclusionCullingData.asset";AssetDatabase.DisallowAutoRefresh();try{foreach(var suffix in new[]{"",".meta"})File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_20261113/before/OcclusionCullingData.asset"+suffix),path+suffix,true);}finally{AssetDatabase.AllowAutoRefresh();}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);
 var parent=GameObject.Find("WildernessEnding");foreach(var t in parent.GetComponentsInChildren<Transform>(true))GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.ReflectionProbeStatic);var factory=GameObject.Find("1F_AbandonedFactory");var old=factory.transform.Find("FactoryViewVolume");if(!old){var g=new GameObject("FactoryViewVolume");g.transform.SetParent(factory.transform,false);var area=g.AddComponent<OcclusionArea>();area.center=new Vector3(0,-4,0);area.size=new Vector3(155,42,125);}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.smallestOccluder=3;StaticOcclusionCulling.smallestHole=.7f;StaticOcclusionCulling.backfaceThreshold=100;bool started=StaticOcclusionCulling.GenerateInBackground();return new{started,exteriorUsesDistanceLOD=true,preservedGUID=AssetDatabase.AssetPathToGUID(path)};}
 public static object Save(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||StaticOcclusionCulling.isRunning)throw new Exception("Edit and finished bake required");EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);Selection.activeGameObject=GameObject.Find("WildernessEnding");SceneView.lastActiveSceneView?.LookAt(new Vector3(-100,3,-29),Quaternion.Euler(5,270,0),30,false,true);return new{saved=!s.isDirty,scene=s.path};}
}
